// код для игрока 
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class playerControler : MonoBehaviour
{
 public float speed = 0.5f;

 private SpriteRenderer sp;
 private Rigidbody2D rb;
 private Vector2 moveVector;

 private void Awake()
 {
 rb = GetComponent<Rigidbody2D>();
 sp = GetComponent<SpriteRenderer>();
 }

 private void FixedUpdate()
 {
 Moving();
 }

 void Moving() 
 {
 rb.MovePosition(rb.position + moveVector * speed * Time.fixedDeltaTime);
 moveVector.x = Input.GetAxis("Horizontal");

 if (moveVector.x < -0.001f)
 sp.flipX = true;
 else if (moveVector.x > 0.001f)
 sp.flipX = false;
 }
}
Код для музыки:
// музыка соответственно
using UnityEngine;
public class Music : MonoBehaviour
{
 [Header("Music clips")]
 [SerializeField] public AudioClip[] Musics;
 private AudioSource _audioSource; 
 void Awake()
 {
 _audioSource = GetComponent<AudioSource>();
 _audioSource.loop = false;
 } 
 void Start()
 {
 if (Musics.Length == 0)
 {
 Debug.LogWarning("The code doesn’t contain any clips!");
 return;
 } 
 StartCoroutine(PlayMusics());
 } 
 private System.Collections.IEnumerator PlayMusics()
 {
 int randomIndex = Random.Range(0, Musics.Length);
 AudioClip randomClip = Musics[randomIndex]; 
 _audioSource.clip = randomClip;
 _audioSource.Play(); 
 yield return new WaitForSeconds(randomClip.length);
 }
}
